using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using SupermarketCatalog.Data;using SupermarketCatalog.Models;
namespace SupermarketCatalog.Pages.Auth;
public class RegisterModel(UserManager<StoreUser> users,SignInManager<StoreUser> signIn,AppDbContext db):PageModel{[BindProperty]public string StoreName{get;set;}="";[BindProperty]public string Email{get;set;}="";[BindProperty]public string Password{get;set;}="";[BindProperty]public string ConfirmPassword{get;set;}="";public string Lang=>Request.Query["lang"].FirstOrDefault()??"ku";public string Dir=>Lang=="en"?"ltr":"rtl";public async Task<IActionResult> OnPostAsync(){if(Password!=ConfirmPassword){ModelState.AddModelError("", "Passwords do not match");return Page();}var u=new StoreUser{UserName=Email,Email=Email,StoreName=StoreName,EmailConfirmed=true,SubscriptionExpiry=DateTime.UtcNow.AddDays(30)};var r=await users.CreateAsync(u,Password);if(!r.Succeeded){foreach(var e in r.Errors)ModelState.AddModelError("",e.Description);return Page();}db.Stores.Add(new Store{Name=StoreName,Email=Email,OwnerId=u.Id});await db.SaveChangesAsync();await signIn.SignInAsync(u,true);return RedirectToPage("/Admin/Index");}}